import { rows } from "../rows.js";

// SCUM: SCUM\Saved\Config\WindowsServer\ServerSettings.ini. Every setting is written `scum.<Name>=<value>` under one of the sections
// [General] [World] [Respawn] [Vehicles] [Damage] [Features]; the form finds a setting by its key alone, so a section the game files
// it under differently doesn't matter. Yes/no settings are True or False.
//
// This is plain data written from the research dossier's table of the file (409 of its 437 settings): the 27 settings the sources
// call unknown, unused, disabled or developer-only are left out, and so is scum.EnableDeenaOnServer, whose source line says only
// "whether Deena is activated". Each row is [key, label, explanation, group]; the explanation is the source's wording tidied up, with
// the default and the range the source gives added at the end. The game's own file is the real inventory: SCUM changes this list
// about once a month, and a setting the file has that is not here is still shown, just without an explanation.

